"""Small payment API with isolated application state per factory call."""

from fastapi import FastAPI, HTTPException, Header, Request, status
from pydantic import BaseModel, Field, validator

from ledger import Ledger
from service import PaymentService


class RefundRequest(BaseModel):
    amount: int = Field(..., gt=0, description="Refund amount in paise")

    @validator("amount")
    def amount_must_be_positive(cls, v):
        if v <= 0:
            raise ValueError("amount must be positive")
        return v


def create_app():
    app = FastAPI()
    service = PaymentService(Ledger())

    @app.get("/payments/{payment_id}")
    def get_payment(payment_id: str):
        try:
            return service.get_payment(payment_id)
        except KeyError:
            raise HTTPException(404, "Payment not found") from None

    @app.post("/payments/{payment_id}/refunds")
    async def refund_payment(
        payment_id: str,
        request: Request,
        refund: RefundRequest,
        idempotency_key: str = Header(..., alias="Idempotency-Key"),
    ):
        # Header validation
        if not (1 <= len(idempotency_key) <= 64) or not all(
            c.isalnum() or c in "-_" for c in idempotency_key
        ):
            raise HTTPException(422, "Invalid Idempotency-Key header")
        try:
            result, status_code = service.refund_payment(
                payment_id, refund.amount, idempotency_key
            )
            return HTTPException(status_code, result) if status_code >= 400 else result
        except HTTPException as exc:
            raise exc
        except Exception as exc:
            raise HTTPException(500, str(exc)) from None

    return app

"""In-memory ledger for a controlled local exercise, not a payment gateway."""

from threading import RLock


class Ledger:
    def __init__(self):
        self.lock = RLock()
        self.payments = {
            "p1": {"id": "p1", "amount": 1000, "refunded": 0, "status": "captured"},
            "p2": {"id": "p2", "amount": 500, "refunded": 0, "status": "captured"},
            "p3": {"id": "p3", "amount": 700, "refunded": 0, "status": "cancelled"},
        }
        self.refunds = {}
        # idempotency_key -> response dict
        self.idempotency = {}

"""Business logic; transport concerns belong in api.py."""

from ledger import Ledger
from fastapi import HTTPException


class PaymentService:
    def __init__(self, ledger: Ledger):
        self.ledger = ledger

    def get_payment(self, payment_id: str) -> dict:
        with self.ledger.lock:
            if payment_id not in self.ledger.payments:
                raise KeyError(payment_id)
            return dict(self.ledger.payments[payment_id])

    def refund_payment(self, payment_id: str, amount: int, idempotency_key: str):
        with self.ledger.lock:
            # Idempotency handling first
            stored = self.ledger.idempotency.get(idempotency_key)
            if stored:
                # If same payment and amount, return stored response (200)
                if (
                    stored["payment_id"] == payment_id
                    and stored["amount"] == amount
                ):
                    return stored["response"], 200
                # Conflict: same key used with different parameters
                raise HTTPException(409, "Idempotency key conflict")

            # Validate payment existence
            payment = self.ledger.payments.get(payment_id)
            if not payment:
                raise HTTPException(404, "Payment not found")

            if payment["status"] != "captured":
                raise HTTPException(409, "Payment not in a refundable state")

            remaining = payment["amount"] - payment["refunded"]
            if amount > remaining:
                raise HTTPException(409, "Refund amount exceeds remaining captured amount")

            # Perform refund mutation
            payment["refunded"] += amount
            if payment["refunded"] == payment["amount"]:
                payment["status"] = "refunded"
                status_str = "refunded"
            else:
                payment["status"] = "partially_refunded"
                status_str = "partially_refunded"

            response = {
                "payment_id": payment_id,
                "amount": amount,
                "refunded_total": payment["refunded"],
                "status": status_str,
            }

            # Store idempotency mapping
            self.ledger.idempotency[idempotency_key] = {
                "payment_id": payment_id,
                "amount": amount,
                "response": response,
            }

            return response, 201
